SELECT DISTINCT p.PROJECT_ID, o.VENDOR_ID from scc_sou_project p
JOIN scc_sou_order o ON o.PROJECT_ID = p.PROJECT_ID  and o.VENDOR_ID IN

    #{item}

JOIN ext_scc_sou_order e on e.ORDER_ID = o.ORDER_ID and e.ORDER_STATUS IN ('SUBMISSION','CANCEL','WITHDRAW' )
WHERE p.SOU_TYPE = 'bid' and p.CREATE_APPROVAL_STATUS='APPROVED' and p.EXT_CATEGORY_ID = #{categoryId}
order by p.PROJECT_ID
